def recognition_html(items):
    """Recognition tiles with an evidence link beside each claim."""
    import html
    esc = html.escape
    return "".join(f'<div><b>{esc(a)}</b><span>{esc(b)}'
                   + (f' <a href="{esc(u)}" rel="noopener">Source</a>' if u else "") + "</span></div>"
                   for a, b, u in items)

